import type { TerminusActivityLogEntry } from "@hunt/public-client";
import type { TerminusTravelLogEntry } from "./TravelLog";

const normalizeTimestamp = (timestamp: Date | string): string =>
  typeof timestamp === "string" ? timestamp : timestamp.toISOString();

export const mapApiLogToTravelLogEntry = (
  log: TerminusActivityLogEntry,
): TerminusTravelLogEntry => {
  const puzzles = (log.data?.puzzles ?? []).map((puzzle) => ({
    slug: puzzle.slug,
    alias: puzzle.alias,
    inUniverse: puzzle.in_universe,
    newlyUnlocked: puzzle.newly_unlocked,
    solved: puzzle.solved,
    title: puzzle.title,
  }));

  return {
    id: log.id,
    timestamp: normalizeTimestamp(log.timestamp),
    terminusState: log.terminus_str,
    puzzles,
    errorMessage: log.error_message ?? undefined,
  };
};
