import { newClient } from "@hunt/public-client";
import {
  ConditionalTooltip,
  PrimarySearchField,
  twemojify as twemojifyOriginal,
} from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import { Loader2, SearchIcon } from "lucide-react";
import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { normalizeTerminusValue } from "../../../../utils/terminus";
import apiUrl from "../../../utils/apiUrl";
import { IS_STATIC_SITE } from "../../../utils/staticSite";
import { TerminusBackButton } from "./TerminusInterface/TerminusInterface";
import TerminusInfoBox from "./TerminusMessageBox/TerminusInfo";
import { mapApiLogToTravelLogEntry } from "./mapTravelLogEntry";
import { loadTerminusLocalState } from "./terminusLocalState";
import { TERMINUS_TOOLTIP_STYLES } from "./terminus_constants";

// Workaround for CI lint error where twemojify is typed as any/error
const twemojify = twemojifyOriginal as (
  text: string,
  className: string,
) => React.ReactNode[];

export type TerminusTravelLogPuzzle = {
  slug: string;
  alias: string;
  inUniverse: boolean;
  newlyUnlocked: boolean;
  solved: boolean;
  title?: string;
};

export type TerminusTravelLogEntry = {
  id: number;
  timestamp: string;
  terminusState: string;
  puzzles: TerminusTravelLogPuzzle[];
  errorMessage?: string;
};

export type TerminusTravelLogPageData = {
  entries: TerminusTravelLogEntry[];
  pageSize: number;
  initialPage: number;
  initialSearch?: string;
  initialOrder: "asc" | "desc";
  initialPuzzleFilters?: string[];
};

type TerminusTravelLogProps = {
  initialPage: TerminusTravelLogPageData;
};

const blackRowBackground = "bg-[rgba(0,0,0,0.80)]";
const blueRowBackground = "bg-[rgba(10,39,128,0.13)]";
const columnWidths = {
  order: { className: "w-[6%]", percent: "6%" },
  timestamp: { className: "w-[8%]", percent: "8%" },
  location: { className: "w-[26%]", percent: "26%" },
  puzzles: { className: "w-[48%]", percent: "48%" },
  snapshot: { className: "w-[12%]", percent: "12%" },
};
const LOCATION_CHAR_LIMIT = 50;
const PAGE_SIZE_OPTIONS = [10, 25, 100];
const PAGE_SIZE_STORAGE_KEY = "terminus_travel_log_page_size";
const getPuzzleSortKey = (puzzle: TerminusTravelLogPuzzle) =>
  (puzzle.title ?? puzzle.alias ?? puzzle.slug).toLocaleLowerCase();

type PuzzleTooltipContentProps = {
  puzzle: TerminusTravelLogPuzzle;
};

const PuzzleFilterTooltipContent: React.FC<PuzzleTooltipContentProps> = ({
  puzzle,
}) => {
  const title = puzzle.title ?? puzzle.slug;
  return (
    <div className="space-y-2">
      <a
        href={`/puzzles/${puzzle.slug}`}
        className="font-semibold text-[#1276F2] underline hover:text-[#63B3FF] transition-colors"
      >
        {title}
      </a>
    </div>
  );
};

const TerminusTravelLog: React.FC<TerminusTravelLogProps> = ({
  initialPage,
}) => {
  const [entries, setEntries] = useState(initialPage.entries);
  const [page, setPage] = useState(initialPage.initialPage);
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">(
    initialPage.initialOrder,
  );
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [searchInput, setSearchInput] = useState(
    initialPage.initialSearch ?? "",
  );
  const [activeSearch, setActiveSearch] = useState(
    initialPage.initialSearch ?? "",
  );
  const [puzzleFilters, setPuzzleFilters] = useState<string[]>(
    () => initialPage.initialPuzzleFilters ?? [],
  );
  const initialPageSize = useMemo(() => {
    if (typeof window !== "undefined") {
      const storedValue = window.localStorage.getItem(PAGE_SIZE_STORAGE_KEY);
      if (storedValue) {
        const parsed = Number.parseInt(storedValue, 10);
        if (PAGE_SIZE_OPTIONS.includes(parsed)) {
          return parsed;
        }
      }
    }
    return PAGE_SIZE_OPTIONS.includes(initialPage.pageSize)
      ? initialPage.pageSize
      : PAGE_SIZE_OPTIONS[0];
  }, [initialPage.pageSize]);
  const [pageSize, setPageSize] = useState(initialPageSize);
  const fetchIdRef = useRef(0);
  const apiClientRef = useRef<ReturnType<typeof newClient> | null>(null);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const params = new URLSearchParams();
    if (page > 1) {
      params.set("page", String(page));
    }
    if (activeSearch) {
      params.set("search", activeSearch);
    }
    if (puzzleFilters.length > 0) {
      const sortedPuzzleFilters = [...puzzleFilters].sort();
      params.set("puzzles", sortedPuzzleFilters.join(","));
    }
    if (pageSize !== PAGE_SIZE_OPTIONS[0]) {
      params.set("pageSize", String(pageSize));
    }
    if (sortDirection === "asc") {
      params.set("order", "asc");
    }
    const query = params.toString();
    const nextUrl =
      query.length > 0
        ? `${window.location.pathname}?${query}`
        : window.location.pathname;
    window.history.replaceState({}, "", nextUrl);
  }, [page, activeSearch, sortDirection, puzzleFilters, pageSize]);
  useEffect(() => {
    if (typeof window === "undefined") return;
    window.localStorage.setItem(PAGE_SIZE_STORAGE_KEY, String(pageSize));
  }, [pageSize]);

  const getApiClient = useCallback(() => {
    if (IS_STATIC_SITE) {
      return null;
    }
    if (apiClientRef.current === null) {
      apiClientRef.current = newClient(apiUrl(), undefined);
    }
    return apiClientRef.current;
  }, []);

  const fetchAllLogs = useCallback(async () => {
    if (IS_STATIC_SITE) {
      setIsLoading(true);
      setError(null);
      try {
        const localState = await loadTerminusLocalState();
        setEntries(localState.travelLog);
      } catch {
        setError("Failed to load travel log entries.");
      } finally {
        setIsLoading(false);
      }
      return;
    }
    fetchIdRef.current += 1;
    const fetchId = fetchIdRef.current;
    setIsLoading(true);
    setError(null);
    try {
      const client = getApiClient();
      if (!client) {
        return;
      }
      const result = await client.getTerminusLogs();
      if (fetchId !== fetchIdRef.current) {
        return;
      }
      if (result.status === 200) {
        setEntries(result.body.logs.map(mapApiLogToTravelLogEntry));
        setError(null);
      } else {
        setError(`Request failed with status ${result.status}`);
      }
    } catch {
      if (fetchId !== fetchIdRef.current) {
        return;
      }
      setError("Failed to load travel log. Please try again.");
    } finally {
      if (fetchId === fetchIdRef.current) {
        setIsLoading(false);
      }
    }
  }, [getApiClient]);

  useEffect(() => {
    if (typeof window === "undefined") return;
    void fetchAllLogs();
  }, [fetchAllLogs]);

  useEffect(() => {
    if (activeSearch && searchInput.trim().length === 0) {
      setActiveSearch("");
      setPage(1);
    }
  }, [activeSearch, searchInput]);

  const normalizedSearch = useMemo(
    () => normalizeTerminusValue(activeSearch),
    [activeSearch],
  );

  const puzzleFilterSet = useMemo(
    () => new Set(puzzleFilters),
    [puzzleFilters],
  );

  const filteredEntries = useMemo(() => {
    const hasPuzzleFilters = puzzleFilterSet.size > 0;
    return entries.filter((entry) => {
      const matchesSearch =
        normalizedSearch.length === 0 ||
        normalizeTerminusValue(entry.terminusState).includes(normalizedSearch);
      if (!matchesSearch) {
        return false;
      }
      if (!hasPuzzleFilters) {
        return true;
      }
      // Build a Set of in-universe puzzle slugs for O(1) lookup
      const inUniverseSlugs = new Set(
        entry.puzzles
          .filter((puzzle) => puzzle.inUniverse)
          .map((puzzle) => puzzle.slug),
      );
      for (const slug of puzzleFilterSet) {
        if (!inUniverseSlugs.has(slug)) {
          return false;
        }
      }
      return true;
    });
  }, [entries, normalizedSearch, puzzleFilterSet]);

  const sortedEntries = useMemo(() => {
    const sorted = [...filteredEntries];
    sorted.sort((a, b) => {
      const aTime = new Date(a.timestamp).getTime();
      const bTime = new Date(b.timestamp).getTime();
      return sortDirection === "desc" ? bTime - aTime : aTime - bTime;
    });
    return sorted;
  }, [filteredEntries, sortDirection]);

  const totalEntries = sortedEntries.length;
  const totalPages =
    totalEntries === 0 ? 1 : Math.max(1, Math.ceil(totalEntries / pageSize));

  useEffect(() => {
    if (page > totalPages) {
      setPage(totalPages);
    }
  }, [page, totalPages]);

  const baseOffset = (page - 1) * pageSize;
  const currentEntries = sortedEntries.slice(baseOffset, baseOffset + pageSize);

  const puzzleMetadataBySlug = useMemo(() => {
    const map = new Map<string, TerminusTravelLogPuzzle>();
    entries.forEach((entry) => {
      entry.puzzles.forEach((puzzle) => {
        if (!map.has(puzzle.slug)) {
          map.set(puzzle.slug, puzzle);
        }
      });
    });
    return map;
  }, [entries]);

  const rows = useMemo(() => {
    return currentEntries.map((entry, index) => {
      const timestamp = new Date(entry.timestamp);
      const hasNewlyUnlocked = entry.puzzles.some(
        (puzzle) => puzzle.newlyUnlocked,
      );
      const puzzles = [...entry.puzzles].sort((a, b) =>
        getPuzzleSortKey(a).localeCompare(getPuzzleSortKey(b)),
      );
      const rawOrder =
        sortDirection === "desc"
          ? totalEntries > 0
            ? totalEntries - (baseOffset + index)
            : currentEntries.length - index
          : baseOffset + index + 1;
      const order = rawOrder > 0 ? rawOrder : index + 1;
      const params = new URLSearchParams();
      if (page > 1) {
        params.set("page", String(page));
      }
      if (activeSearch) {
        params.set("search", activeSearch);
      }
      if (sortDirection === "asc") {
        params.set("order", "asc");
      }
      const query = params.toString();
      return {
        ...entry,
        puzzles,
        order,
        formattedDate: timestamp.toLocaleDateString(),
        formattedTime: timestamp.toLocaleTimeString(),
        href: query
          ? `/rounds/terminus/travel_log/${entry.id}?${query}`
          : `/rounds/terminus/travel_log/${entry.id}`,
        hasNewlyUnlocked,
      };
    });
  }, [
    activeSearch,
    baseOffset,
    currentEntries,
    page,
    sortDirection,
    totalEntries,
  ]);

  const rowCount = rows.length;
  const showingStart = rowCount === 0 ? 0 : baseOffset + 1;
  const showingEnd = rowCount === 0 ? 0 : baseOffset + rowCount;
  const canGoPrev = page > 1;
  const canGoNext = page < totalPages;

  const handleSortToggle = () => {
    setSortDirection((prev) => (prev === "desc" ? "asc" : "desc"));
    setPage(1);
  };

  const handlePrevPage = () => {
    if (canGoPrev) {
      setPage((prev) => Math.max(prev - 1, 1));
    }
  };

  const handleNextPage = () => {
    if (canGoNext) {
      setPage((prev) => prev + 1);
    }
  };

  const handleSearchSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const trimmed = searchInput.trim();
    setActiveSearch(trimmed);
    setPage(1);
  };

  const handlePageSizeChange = useCallback((nextPageSize: number) => {
    if (!PAGE_SIZE_OPTIONS.includes(nextPageSize)) {
      return;
    }
    setPageSize(nextPageSize);
    setPage(1);
  }, []);

  const handlePuzzleFilterToggle = useCallback((slug: string) => {
    setPuzzleFilters((prev) => {
      if (prev.includes(slug)) {
        return prev.filter((filterSlug) => filterSlug !== slug);
      }
      return [...prev, slug];
    });
    setPage(1);
  }, []);

  const handleClearPuzzleFilters = useCallback(() => {
    setPuzzleFilters([]);
    setPage(1);
  }, []);

  const hasActiveFilters = activeSearch.length > 0 || puzzleFilters.length > 0;

  const summarySuffix = hasActiveFilters
    ? `result${totalEntries === 1 ? "" : "s"}`
    : `entr${totalEntries === 1 ? "y" : "ies"}`;

  const emptyStateMessage = hasActiveFilters
    ? "No travel log entries match the current filters."
    : "No Terminus travel recorded yet.";

  return (
    <div className="space-y-6">
      <TerminusBackButton
        href="/rounds/terminus"
        text="Back to Terminus"
        className="text-sm font-semibold"
      />
      <form onSubmit={handleSearchSubmit} className="max-w-full">
        <PrimarySearchField
          name="terminus-travel-log-search"
          value={searchInput}
          onChange={(event: React.ChangeEvent<HTMLInputElement>) => {
            setSearchInput(event.target.value);
          }}
          placeholder="Search locations…"
          aria-label="Search travel log entries by Terminus input"
          leftIcon={SearchIcon}
          disabled={isLoading}
        />
      </form>
      {puzzleFilters.length > 0 && (
        <div className="flex flex-wrap items-center gap-2 rounded-sm border border-[#707070] bg-black/40 px-3 py-2 text-xs text-white">
          <span className="text-[#A4A4A4] uppercase tracking-wide">
            Filtered puzzles:
          </span>
          {puzzleFilters.map((slug) => {
            const puzzle =
              puzzleMetadataBySlug.get(slug) ??
              ({
                slug,
                alias: slug,
                inUniverse: false,
                newlyUnlocked: false,
                solved: false,
                title: slug,
              } satisfies TerminusTravelLogPuzzle);
            const label = puzzle.alias ?? puzzle.title ?? puzzle.slug ?? slug;
            return (
              <ConditionalTooltip
                key={slug}
                className={cn(TERMINUS_TOOLTIP_STYLES, "max-h-24 space-y-2")}
                tooltip={<PuzzleFilterTooltipContent puzzle={puzzle} />}
              >
                <button
                  type="button"
                  onClick={() => {
                    handlePuzzleFilterToggle(slug);
                  }}
                  className="inline-flex items-center gap-1 rounded-sm border border-white/30 bg-white/10 px-2 py-0.5 font-mono text-[11px] uppercase tracking-wide text-white transition-colors hover:border-white hover:text-[#15FF00]"
                  aria-label={`Remove filter for ${label}`}
                >
                  {label}
                  <span className="text-[#FF5F5F]">×</span>
                </button>
              </ConditionalTooltip>
            );
          })}
          <button
            type="button"
            onClick={handleClearPuzzleFilters}
            className="ml-auto rounded-sm border border-white/30 px-2 py-0.5 uppercase tracking-wide text-[11px] text-[#A4A4A4] transition-colors hover:border-white hover:text-white"
          >
            Clear all
          </button>
        </div>
      )}
      {error && (
        <div className="text-sm text-[#FF5F5F]" role="alert">
          {error}
        </div>
      )}
      <TerminusInfoBox
        inline
        fullSize
        className="gap-4"
        iconClassName="w-7 h-7"
      >
        <p>
          Hover over locations and puzzle IDs to see the full location or puzzle
          name.
        </p>
        <p className="mt-0">
          Click on puzzles to filter for locations that contain ALL selected
          puzzles.
        </p>
        <p className="mt-0">
          Snapshots provide a non-interactive version of the main page.
        </p>
      </TerminusInfoBox>
      <div className="border border-[#707070] bg-black/30 shadow-inner">
        {totalEntries > 0 && (
          <div
            className="grid gap-3 border-b border-[#707070] bg-black/60 px-4 py-3 text-xs text-[#A4A4A4] items-center"
            style={{ gridTemplateColumns: "1fr auto 1fr" }}
          >
            <div className="flex items-center gap-2 justify-self-start">
              <span>
                Showing {showingStart}–{showingEnd} of {totalEntries}{" "}
                {summarySuffix}
              </span>
              {isLoading && (
                <Loader2
                  className="h-4 w-4 animate-spin text-white"
                  aria-label="Loading travel log entries"
                />
              )}
            </div>
            <div className="flex items-center justify-center gap-3 justify-self-center">
              <button
                type="button"
                onClick={handlePrevPage}
                disabled={!canGoPrev || isLoading}
                className={cn(
                  "rounded-sm border border-[#707070] px-3 py-1 font-semibold text-white transition-colors",
                  !canGoPrev || isLoading
                    ? "cursor-not-allowed opacity-40"
                    : "hover:bg-white/10",
                )}
              >
                Previous
              </button>
              <div className="font-mono text-white">
                Page {page} / {totalPages}
              </div>
              <button
                type="button"
                onClick={handleNextPage}
                disabled={!canGoNext || isLoading}
                className={cn(
                  "rounded-sm border border-[#707070] px-3 py-1 font-semibold text-white transition-colors",
                  !canGoNext || isLoading
                    ? "cursor-not-allowed opacity-40"
                    : "hover:bg-white/10",
                )}
              >
                Next
              </button>
            </div>
            <div className="flex flex-wrap items-center justify-end gap-2 text-[11px] uppercase tracking-wide text-[#A4A4A4] text-right justify-self-end">
              <label
                htmlFor="terminus-travel-log-page-size"
                className="font-semibold"
              >
                Page size
              </label>
              <select
                id="terminus-travel-log-page-size"
                className="rounded-sm border border-white/30 bg-[#050505] px-2 py-1 font-semibold text-white focus:outline-none focus-visible:ring-2 focus-visible:ring-[#15FF00]/60"
                value={String(pageSize)}
                onChange={(event) => {
                  handlePageSizeChange(Number(event.target.value));
                }}
              >
                {PAGE_SIZE_OPTIONS.map((size) => (
                  <option key={size} value={size} className="bg-[#050505]">
                    {size}
                  </option>
                ))}
              </select>
            </div>
          </div>
        )}
        <div className="overflow-x-auto">
          <table className="min-w-full table-fixed border-separate border-spacing-0 text-sm text-white">
            <colgroup>
              <col style={{ width: columnWidths.order.percent }} />
              <col style={{ width: columnWidths.timestamp.percent }} />
              <col style={{ width: columnWidths.location.percent }} />
              <col style={{ width: columnWidths.puzzles.percent }} />
              <col style={{ width: columnWidths.snapshot.percent }} />
            </colgroup>
            <thead>
              <tr className="bg-[#A4A4A4] text-[#050505] uppercase tracking-wide">
                <th
                  className={cn(
                    columnWidths.order.className,
                    "px-3 py-2 text-center font-semibold align-middle",
                  )}
                  scope="col"
                >
                  <button
                    type="button"
                    onClick={handleSortToggle}
                    className="flex w-full items-center justify-center gap-1 text-center font-semibold uppercase tracking-wide focus:outline-none focus-visible:ring-2 focus-visible:ring-[#15FF00]/60"
                  >
                    <span>#</span>
                    <span aria-hidden="true">
                      {sortDirection === "desc" ? "▼" : "▲"}
                    </span>
                    <span className="sr-only">
                      Toggle sort order (currently{" "}
                      {sortDirection === "desc" ? "newest" : "oldest"} first)
                    </span>
                  </button>
                </th>
                <th
                  className={cn(
                    columnWidths.timestamp.className,
                    "px-3 py-2 text-center font-semibold align-middle",
                  )}
                  scope="col"
                >
                  Timestamp
                </th>
                <th
                  className={cn(
                    columnWidths.location.className,
                    "px-3 py-2 text-center font-semibold align-middle",
                  )}
                  scope="col"
                >
                  Location
                </th>
                <th
                  className={cn(
                    columnWidths.puzzles.className,
                    "px-3 py-2 text-center font-semibold align-middle",
                  )}
                  scope="col"
                >
                  Puzzles
                </th>
                <th
                  className={cn(
                    columnWidths.snapshot.className,
                    "px-3 py-2 text-center font-semibold align-middle",
                  )}
                  scope="col"
                >
                  Snapshot
                </th>
              </tr>
            </thead>
            <tbody>
              {rowCount === 0 ? (
                <tr className="bg-black/60">
                  <td
                    className="px-3 py-6 text-center text-sm text-muted-foreground border-l border-r border-b border-dashed border-[#707070]"
                    colSpan={5}
                  >
                    {emptyStateMessage}
                  </td>
                </tr>
              ) : (
                rows.map((row, index) => {
                  const rowBackground =
                    index % 2 === 0 ? blackRowBackground : blueRowBackground;
                  const cellBase =
                    "px-3 py-3 align-middle border-l border-b border-dashed border-[#707070] first:border-l last:border-r";
                  const isLocationTruncated =
                    row.terminusState.length > LOCATION_CHAR_LIMIT;
                  const truncatedLocation = isLocationTruncated
                    ? `${row.terminusState.slice(0, LOCATION_CHAR_LIMIT)}…`
                    : row.terminusState;
                  const hasError = row.errorMessage !== undefined;
                  const tooltipLines: React.ReactNode[] = [];
                  if (isLocationTruncated) {
                    tooltipLines.push(
                      <p key="location">{row.terminusState}</p>,
                    );
                  }
                  if (hasError) {
                    tooltipLines.push(
                      <p key="error" className="text-[#FF5F5F] font-semibold">
                        {row.errorMessage}
                      </p>,
                    );
                  }
                  const locationTooltip =
                    tooltipLines.length > 0 ? (
                      <div className="space-y-1 text-left">{tooltipLines}</div>
                    ) : undefined;
                  const locationClasses = cn(
                    "block whitespace-normal break-words font-mono text-xs",
                    hasError
                      ? "text-[#FF5F5F] font-semibold"
                      : "text-[#FFE100] font-semibold",
                  );

                  return (
                    <tr key={row.id} className={rowBackground}>
                      <td
                        className={cn(
                          cellBase,
                          columnWidths.order.className,
                          "font-semibold text-sm text-center",
                        )}
                      >
                        {row.order}
                      </td>
                      <td
                        className={cn(
                          cellBase,
                          columnWidths.timestamp.className,
                          "whitespace-normal break-words text-sm text-center",
                        )}
                      >
                        <div className="space-y-0.5">
                          <div>{row.formattedDate}</div>
                          <div className="text-xs text-[#A4A4A4]">
                            {row.formattedTime}
                          </div>
                        </div>
                      </td>
                      <td
                        className={cn(
                          cellBase,
                          columnWidths.location.className,
                          "text-center",
                        )}
                      >
                        <ConditionalTooltip
                          className={cn(TERMINUS_TOOLTIP_STYLES, "max-h-20")}
                          tooltip={locationTooltip}
                        >
                          <span className={locationClasses}>
                            {twemojify(truncatedLocation, "h-3")}
                          </span>
                        </ConditionalTooltip>
                      </td>
                      <td
                        className={cn(
                          cellBase,
                          columnWidths.puzzles.className,
                          "text-center",
                        )}
                      >
                        {row.puzzles.length === 0 ? (
                          <span className="text-xs text-[#707070] italic">
                            No puzzles discovered.
                          </span>
                        ) : (
                          <div className="flex flex-wrap justify-center gap-x-3 gap-y-1 text-xs uppercase tracking-wide text-center">
                            {row.puzzles.map((puzzle) => {
                              const isFiltered = puzzleFilterSet.has(
                                puzzle.slug,
                              );
                              return (
                                <ConditionalTooltip
                                  key={`${row.id}-${puzzle.slug}`}
                                  className={cn(
                                    TERMINUS_TOOLTIP_STYLES,
                                    "max-h-24 space-y-2",
                                  )}
                                  tooltip={
                                    <PuzzleFilterTooltipContent
                                      puzzle={puzzle}
                                    />
                                  }
                                >
                                  <button
                                    type="button"
                                    onClick={() => {
                                      handlePuzzleFilterToggle(puzzle.slug);
                                    }}
                                    className={cn(
                                      "font-mono transition-opacity hover:opacity-80 hover:text-current",
                                      puzzle.inUniverse
                                        ? "text-[#FFE100] underline font-semibold"
                                        : "text-[#707070]",
                                      isFiltered &&
                                        "rounded-sm bg-white/10 px-1 text-[#15FF00] underline decoration-[#15FF00]",
                                    )}
                                    aria-pressed={isFiltered}
                                  >
                                    {puzzle.alias}
                                  </button>
                                </ConditionalTooltip>
                              );
                            })}
                          </div>
                        )}
                      </td>
                      <td
                        className={cn(
                          cellBase,
                          columnWidths.snapshot.className,
                          "text-center",
                        )}
                      >
                        <a
                          href={row.href}
                          className="text-[#15FF00] font-semibold tracking-wide hover:underline hover:text-[#15FF00] transition-opacity hover:opacity-80"
                        >
                          View
                        </a>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default TerminusTravelLog;
