import { type TeamHuntState } from "@hunt/public-client";
import React from "react";
import { hydrateRoot } from "react-dom/client";
import { TeamStateProvider } from "../components/TeamStateProvider";
import TerminusTravelLog, {
  type TerminusTravelLogPageData,
} from "../rounds/dimensions/terminus/TravelLog";
import useDataset from "./useDataset";

const TerminusTravelLogManager = ({
  initialPage,
  initialTeamState,
}: {
  initialPage: TerminusTravelLogPageData;
  initialTeamState: TeamHuntState;
}) => {
  const teamState = useDataset("team_state", undefined, initialTeamState);

  return (
    <TeamStateProvider teamState={teamState}>
      <TerminusTravelLog initialPage={initialPage} />
    </TeamStateProvider>
  );
};

const elem = document.getElementById("terminus-travel-log-root");
if (elem) {
  const { initialTerminusTravelLogPage, initialTeamState } =
    window as unknown as {
      initialTerminusTravelLogPage: TerminusTravelLogPageData | undefined;
      initialTeamState: TeamHuntState;
    };
  const fallbackPage: TerminusTravelLogPageData = {
    entries: [],
    pageSize: 10,
    initialPage: 1,
    initialSearch: "",
    initialOrder: "desc",
    initialPuzzleFilters: [],
  };
  hydrateRoot(
    elem,
    <TerminusTravelLogManager
      initialPage={initialTerminusTravelLogPage ?? fallbackPage}
      initialTeamState={initialTeamState}
    />,
  );
} else {
  console.error(
    "Could not mount TerminusTravelLog because #terminus-travel-log-root was nowhere to be found",
  );
}
